<script>
(function(){var input=document.querySelector('#pc-search-form input[name="buscar"]'),results=document.getElementById('pc-results'),status=document.getElementById('pc-search-status'),timer;
function search(){var params=new URLSearchParams();var agenda=document.querySelector('#pc-search-form input[name="agenda"]');if(agenda)params.set('agenda',agenda.value);params.set('buscar',input.value);var url='{{ route('v3.preparations.catalog') }}?'+params.toString();status.textContent='Buscando...';results.style.opacity='.45';fetch(url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}}).then(function(r){if(!r.ok)throw new Error();return r.text();}).then(function(html){results.innerHTML=html;history.replaceState(null,'',url);status.textContent='';results.style.opacity='1';}).catch(function(){status.textContent='No se pudo realizar la búsqueda.';results.style.opacity='1';});}
input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(search,300);});document.getElementById('pc-search-form').addEventListener('submit',function(e){e.preventDefault();search();});})();
</script>
